from scipy.optimize import least_squares
import itertools,time
rng=np.random.default_rng(5)
a=np.abs
def vp(cols,n,tries=4):
    best=(1e9,None,None)
    def R(q):
        A=np.column_stack(cols(q)); A=np.nan_to_num(A,nan=1e3,posinf=1e3,neginf=-1e3)
        c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]; return A@c-dP_dt,c
    for k in range(tries):
        q0=rng.uniform(0.3,1.5,n)
        try:
            r=least_squares(lambda q:R(q)[0],q0,max_nfev=150)
            v=np.mean(r.fun**2)/np.var(dP_dt)
            if v<best[0]: best=(v,r.x,R(r.x)[1])
        except Exception as e: pass
    return best
